actions.script:
// Keep the date filter valid before it reaches the entity query.
def requestedDate = (ec.web.parameters.filterDate ?: '').toString()
def selectedDate
try { selectedDate = java.time.LocalDate.parse(requestedDate) }
catch (Exception ignored) { selectedDate = java.time.LocalDate.parse(ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')) }
filterDate = selectedDate.toString()
dayStart = ec.l10n.parseTimestamp(filterDate + ' 00:00:00', 'yyyy-MM-dd HH:mm:ss')
dayEnd = ec.l10n.parseTimestamp(selectedDate.plusDays(1).toString() + ' 00:00:00', 'yyyy-MM-dd HH:mm:ss')
priorStart = ec.l10n.parseTimestamp(selectedDate.minusDays(1).toString() + ' 00:00:00', 'yyyy-MM-dd HH:mm:ss')
orgId = posOrganizationPartyId ?: '__NO_ORGANIZATION__'
def shopScope = ec.service.sync().name('zenith.base.ShopServices.get#ActiveShopScope')
    .parameter('includePosScope', true).call()
shopSessionIds = shopScope?.sessionIds

def zero = BigDecimal.ZERO
def money = { n -> zinr.inr(ec.l10n.format((n ?: zero) as BigDecimal, '#,##0.00')) }
def sumFor = { rows, kind, field ->
    rows.findAll { kind == null || (kind == 'Sale' ? it.transactionType != 'Return' : it.transactionType == 'Return') }
        .sum { ((it[field] ?: zero) as BigDecimal).abs() } ?: zero
}
def metricsFor = { rows ->
    def sales = sumFor(rows, 'Sale', 'grandTotal')
    def returns = sumFor(rows, 'Return', 'grandTotal')
    def saleRows = rows.findAll { it.transactionType != 'Return' }
    [sales:sales, returns:returns, net:sales - returns,
     tax:sumFor(saleRows, null, 'totalTaxAmount') - sumFor(rows.findAll { it.transactionType == 'Return' }, null, 'totalTaxAmount'),
     transactions:rows.size(),
     average:saleRows ? sales.divide(new BigDecimal(saleRows.size()), 2, java.math.RoundingMode.HALF_UP) : zero]
}
def current = metricsFor(completedTxns)
def previous = metricsFor(priorTxns)
def comparison = { now, before, isCount ->
    def n = now as BigDecimal
    def p = before as BigDecimal
    if (p == zero) return [change:(n == zero ? '0.0%' : 'New'), direction:(n == zero ? 'flat' : 'up'),
                           previous:(isCount ? p.toInteger().toString() : money(p))]
    def pct = n.subtract(p).abs().multiply(new BigDecimal('100')).divide(p.abs(), 1, java.math.RoundingMode.HALF_UP)
    [change:pct.toPlainString() + '%', direction:(n > p ? 'up' : n < p ? 'down' : 'flat'),
     previous:(isCount ? p.toInteger().toString() : money(p))]
}
summaryCards = [
    [key:'sales', label:'Total Sales', icon:'shopping_bag', tone:'green', count:false],
    [key:'returns', label:'Returns', icon:'assignment_return', tone:'red', count:false],
    [key:'net', label:'Net Sales', icon:'bar_chart', tone:'purple', count:false],
    [key:'tax', label:'Tax Collected', icon:'account_balance_wallet', tone:'orange', count:false],
    [key:'transactions', label:'Transactions', icon:'receipt_long', tone:'blue', count:true],
    [key:'average', label:'Avg. Ticket', icon:'local_offer', tone:'violet', count:false]
].collect { card ->
    def delta = comparison(current[card.key], previous[card.key], card.count)
    card + [value:(card.count ? current[card.key].toString() : money(current[card.key])),
            change:delta.change, direction:delta.direction, previous:delta.previous]
}

// The payment chart describes tender received for completed sales on this date.
def saleIds = completedTxns.findAll { it.transactionType != 'Return' }.collect { it.transactionId }
def payments = saleIds ? ec.entity.find('zenith.erp.pos.PosPayment')
    .condition('transactionId', 'in', saleIds).list() : []
def paymentTotals = [Cash:zero, UPI:zero, Card:zero, Other:zero]
payments.each { pay ->
    def amount = (pay.amount ?: zero) as BigDecimal
    if (amount > zero) {
        def method = pay.paymentMethod in ['Cash', 'UPI', 'Card'] ? pay.paymentMethod : 'Other'
        paymentTotals[method] += amount
    }
}
paymentTotal = paymentTotals.values().sum() ?: zero
def paymentColors = [Cash:'#4169ef', UPI:'#08b96e', Card:'#722df4', Other:'#ff8b11']
paymentBreakdown = paymentTotals.collect { method, amount ->
    [method:method, amount:money(amount), color:paymentColors[method],
     percent:paymentTotal > zero ? amount.multiply(new BigDecimal('100')).divide(paymentTotal, 2, java.math.RoundingMode.HALF_UP).toPlainString() : '0.00']
}
def segments = []
def angle = 0.0d
paymentBreakdown.each { row ->
    def next = angle + (row.percent as double)
    segments.add(row.color + ' ' + String.format(java.util.Locale.US, '%.2f', angle) + '% ' +
        String.format(java.util.Locale.US, '%.2f', next) + '%')
    angle = next
}
paymentGradient = paymentTotal > zero ? 'conic-gradient(' + segments.join(', ') + ')' : 'conic-gradient(#e9eaf4 0 100%)'
paymentTotalDisplay = money(paymentTotal)

// Keep all hours containing sales, with the reference's 09 AM–08 PM range as the minimum.
def saleTxns = completedTxns.findAll { it.transactionType != 'Return' && it.entryDate }
def hours = saleTxns.collect {
    def cal = java.util.Calendar.getInstance(); cal.setTime(it.entryDate); cal.get(java.util.Calendar.HOUR_OF_DAY)
}
def startHour = hours ? Math.min(9, hours.min() as int) : 9
def endHour = hours ? Math.max(20, hours.max() as int) : 20
def hourly = (startHour..endHour).collect { h -> [hour:h, amount:zero] }
saleTxns.each { tx ->
    def cal = java.util.Calendar.getInstance(); cal.setTime(tx.entryDate)
    hourly[cal.get(java.util.Calendar.HOUR_OF_DAY) - startHour].amount += ((tx.grandTotal ?: zero) as BigDecimal).abs()
}
hasHourlySales = hourly.any { it.amount > zero }
def largest = hourly.collect { it.amount }.max() ?: zero
def scale = largest > zero ? largest.multiply(new BigDecimal('1.15')) : new BigDecimal('1000')
def compact = { value ->
    if (value >= 100000) return '₹' + value.divide(new BigDecimal('100000'), 1, java.math.RoundingMode.HALF_UP) + 'L'
    if (value >= 1000) return '₹' + value.divide(new BigDecimal('1000'), 1, java.math.RoundingMode.HALF_UP) + 'K'
    return '₹' + value.setScale(0, java.math.RoundingMode.HALF_UP)
}
def plotLeft = 52.0d, plotRight = 728.0d, plotTop = 22.0d, plotBottom = 183.0d
chartTicks = (0..4).collect { i ->
    def amount = scale.multiply(new BigDecimal(i)).divide(new BigDecimal('4'), 2, java.math.RoundingMode.HALF_UP)
    [y:(plotBottom - i * (plotBottom - plotTop) / 4), label:compact(amount)]
}
chartPoints = []
hourly.eachWithIndex { slot, i ->
    def x = plotLeft + i * (plotRight - plotLeft) / Math.max(1, hourly.size() - 1)
    def y = plotBottom - (slot.amount.doubleValue() / scale.doubleValue()) * (plotBottom - plotTop)
    def hourLabel = String.format('%02d', (slot.hour % 12 == 0 ? 12 : slot.hour % 12)) + (slot.hour < 12 ? ' AM' : ' PM')
    chartPoints << [x:x, y:y, label:hourLabel, amountLabel:compact(slot.amount), hasValue:slot.amount > zero]
}
chartPolyline = chartPoints.collect { String.format(java.util.Locale.US, '%.1f,%.1f', it.x, it.y) }.join(' ')
chartArea = String.format(java.util.Locale.US, '%.1f,%.1f ', plotLeft, plotBottom) +
    chartPolyline + String.format(java.util.Locale.US, ' %.1f,%.1f', plotRight, plotBottom)
recentTransactions = completedTxns.take(5).collect { tx ->
    [id:tx.transactionId, number:(tx.transactionNumber ?: tx.transactionId),
     type:(tx.transactionType ?: 'Sale'),
     time:(tx.entryDate ? ec.l10n.format(tx.entryDate, 'hh:mm a') : '—'),
     customer:(tx.customerName ?: 'Walk-in Customer'),
     subtotal:money(tx.subtotal), tax:money(tx.totalTaxAmount),
     discount:money(tx.discountTotal), total:money(tx.grandTotal)]
}
